from .cycle import CircularDependencyError

class DependencyResolver:
    def __init__(self, deps: dict[str, list[str]]):
        self.deps = deps

    def resolve(self) -> list[str]:
        # In-degree computation for Kahn's algorithm
        nodes = set(self.deps.keys())
        for targets in self.deps.values(): nodes.update(targets)
        in_degree = {n: 0 for n in nodes}
        for targets in self.deps.values():
            for t in targets: in_degree[t] += 1
        queue = sorted([n for n, deg in in_degree.items() if deg == 0])
        res = []
        while queue:
            curr = queue.pop(0)
            res.append(curr)
            for nxt in sorted(self.deps.get(curr, [])):
                in_degree[nxt] -= 1
                if in_degree[nxt] == 0: queue.append(nxt)
            queue.sort()
        if len(res) < len(nodes):
            cycle = self._find_cycle()
            raise CircularDependencyError('Cycle detected', cycle)
        return res

    def _find_cycle(self) -> list[str]:
        # DFS to find a cycle in the remaining (unresolved) nodes
        remaining = set(self.deps.keys())
        for r in self.deps.values(): remaining.update(r)
        # Only consider nodes not in the resolved order
        resolved = set()
        # We'll just run DFS over all nodes to find any cycle.
        WHITE, GRAY, BLACK = 0, 1, 2
        color = {n: WHITE for n in remaining}
        stack = []

        def dfs(node):
            color[node] = GRAY
            stack.append(node)
            for nxt in sorted(self.deps.get(node, [])):
                if nxt not in color:
                    continue
                if color[nxt] == GRAY:
                    # Found cycle: from nxt back to node
                    idx = stack.index(nxt)
                    return stack[idx:] + [nxt]
                if color[nxt] == WHITE:
                    result = dfs(nxt)
                    if result:
                        return result
            stack.pop()
            color[node] = BLACK
            return None

        for n in sorted(remaining):
            if color[n] == WHITE:
                result = dfs(n)
                if result:
                    return result
        return []
